<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Çeviri yönetimi</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px;margin:15px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #edf0ed}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}textarea{min-height:50px}button{background:#176b50;color:white;border:0;padding:11px 16px;border-radius:8px;font-weight:700}.key{font-family:monospace;font-size:12px;color:#68756c}</style></head><body><main class="wrap"><h1>Çeviri yönetimi</h1><form method="get" action="/admin/translations"><select name="lang" onchange="this.form.submit()"><?php foreach($languages as $language): ?><option value="<?= e($language['code']) ?>" <?= $language['code']===$locale?'selected':'' ?>><?= e($language['name']) ?> (<?= e($language['code']) ?>)</option><?php endforeach; ?></select></form><form method="post" action="/admin/translations"><?= csrf_field() ?><input type="hidden" name="lang" value="<?= e($locale) ?>"><section class="panel"><table><thead><tr><th>Çeviri anahtarı</th><th>Metin</th></tr></thead><tbody><?php foreach($translations as $key=>$value): ?><tr><td class="key"><?= e($key) ?></td><td><textarea name="translations[<?= e($key) ?>]"><?= e($value) ?></textarea></td></tr><?php endforeach; ?></tbody></table><p><button type="submit">Çevirileri kaydet</button></p></section></form><form method="post" action="/admin/translations"><?= csrf_field() ?><input type="hidden" name="lang" value="<?= e($locale) ?>"><section class="panel"><h2>Yeni çeviri anahtarı</h2><input name="new_key" placeholder="translation.key" required><textarea name="new_value" placeholder="Çeviri metni" required></textarea><p><button type="submit">Yeni anahtar ekle</button></p></section></form><p><a href="/admin">Yönetim paneli</a></p></main></body></html>